const scripts = `const navToggle=document.querySelector('#nav-toggle'),sidebar=document.querySelector('#sidebar'),navBackdrop=document.querySelector('#nav-backdrop');
function setNav(open){if(!sidebar)return;sidebar.classList.toggle('is-open',open);navBackdrop.hidden=!open;navToggle.setAttribute('aria-expanded',String(open))}
navToggle?.addEventListener('click',()=>setNav(!sidebar.classList.contains('is-open')));navBackdrop?.addEventListener('click',()=>setNav(false));addEventListener('keydown',e=>{if(e.key==='Escape')setNav(false)});
document.querySelectorAll('.sidebar-nav a').forEach(a=>{const href=a.getAttribute('href');if(href==='/'?location.pathname==='/':location.pathname.startsWith(href))a.setAttribute('aria-current','page')});
document.querySelectorAll('[data-confirm]').forEach(x=>x.addEventListener('click',e=>{if(!confirm(x.dataset.confirm))e.preventDefault()}));
const asset=document.querySelector('#asset'),price=document.querySelector('#price'),status=document.querySelector('#price-status'),fx=document.querySelector('#fx-rate'),fxStatus=fx?.nextElementSibling;
if(asset)asset.addEventListener('change',async()=>{const o=asset.selectedOptions[0];if(!o.value)return;if(o.dataset.fixed==='true'){price.value='1';status.textContent='Fixed native-currency price'}else{status.textContent='Loading current price…';try{const r=await fetch('/api/assets/'+o.value+'/price',{headers:{Accept:'application/json'}});if(!r.ok)throw Error(await r.text());const q=await r.json();price.value=q.price;status.textContent=q.source+' · '+q.timestamp+' · '+q.currency+'. Editable before saving.'}catch(e){status.textContent='Automatic price unavailable. Enter a manual price.'}}if(o.dataset.currency==='IDR'){fx.value='1';if(fxStatus)fxStatus.textContent='Native IDR asset · fixed conversion rate 1.'}else{if(fxStatus)fxStatus.textContent='Loading USD/IDR…';try{const r=await fetch('/api/exchange-rate',{headers:{Accept:'application/json'}});if(!r.ok)throw Error(await r.text());const q=await r.json();fx.value=q.rate;if(fxStatus)fxStatus.textContent=q.source+' · '+q.timestamp+'. Editable before saving.'}catch(e){if(fxStatus)fxStatus.textContent='Automatic USD/IDR unavailable. Enter the applicable rate manually.'}}});
`

const styles = `:root{--bg:#f7f2ea;--panel:#fffdf9;--ink:#2e2924;--muted:#746b62;--line:#ded3c6;--brand:#a94f2c;--brand2:#7d391f;--gain:#23714d;--loss:#ad3232;--radius:16px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,sans-serif}a{color:var(--brand2)}header{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:14px max(20px,calc((100vw - 1180px)/2));background:#fffaf3ee;border-bottom:1px solid var(--line);backdrop-filter:blur(8px)}.brand{font-size:1.4rem;font-weight:800;text-decoration:none}nav{display:flex;align-items:center;gap:18px}nav a,button.link{color:var(--ink);text-decoration:none;background:none;border:0;padding:8px;font:inherit}nav form{margin:0}main{width:min(1180px,calc(100% - 32px));margin:36px auto 64px}.narrow{width:min(480px,calc(100% - 32px));margin-top:10vh}.title{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}.eyebrow{margin:0;color:var(--brand);font-weight:700;text-transform:uppercase;letter-spacing:.08em;font-size:.75rem}h1{margin:.15rem 0;font-size:clamp(1.9rem,5vw,3rem)}h2{font-size:1.15rem;margin:0 0 16px}.panel,.metrics article{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:0 5px 18px #4c2c1810}.grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;margin-bottom:18px}.metrics article span,.metrics article small{display:block;color:var(--muted)}.metrics strong{display:block;font-size:1.35rem;margin-top:6px}.gain{color:var(--gain)}.loss{color:var(--loss)}.actions{display:flex;gap:10px;justify-content:flex-end;margin:-62px 0 24px}.actions form{margin:0}button,.button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;border:0;border-radius:11px;padding:10px 17px;background:var(--brand);color:white;font:600 1rem inherit;text-decoration:none;cursor:pointer}button:hover,.button:hover{background:var(--brand2)}.secondary{background:#ebe1d5;color:var(--ink)}.danger{background:#9b3535}form{display:grid;gap:16px}label{display:grid;gap:6px;font-weight:650}input,select,textarea{width:100%;min-height:44px;border:1px solid #bcae9e;border-radius:10px;background:white;padding:9px 11px;color:var(--ink);font:inherit}textarea{resize:vertical}input:focus,select:focus,textarea:focus,button:focus,a:focus{outline:3px solid #e49a6599;outline-offset:2px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.inline{display:flex;grid-template-columns:1fr auto auto;margin:10px 0}.filters{display:flex;align-items:end;margin-bottom:20px}.filters label{min-width:220px}.table{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:13px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:.8rem;text-transform:uppercase;color:var(--muted)}td small{display:block;color:var(--muted)}.tag{display:inline-block;border-radius:99px;background:#eee4d8;padding:3px 8px;font-size:.75rem;text-transform:capitalize}.warn{background:#fff0bf;color:#674c00}.empty,.alert{padding:20px;border-radius:12px;background:#f2e9df;color:var(--muted)}.alert{margin-bottom:18px}.alert.error{background:#fbe1df;color:#7e2020}.muted,small{color:var(--muted)}dl{display:grid;grid-template-columns:140px 1fr;gap:8px}dt{font-weight:700}dd{margin:0}.bars div{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--line)}footer{text-align:center;color:var(--muted);padding:24px}@media(max-width:850px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}header{align-items:flex-start;gap:10px}nav{gap:4px;flex-wrap:wrap;justify-content:flex-end}.actions{margin:0 0 18px;justify-content:flex-start}}@media(max-width:560px){main{width:min(100% - 20px,1180px);margin-top:22px}header{position:static;display:block}.brand{display:block;margin-bottom:8px}nav{justify-content:flex-start}nav a,button.link{padding:7px;font-size:.9rem}.metrics,.form-grid{grid-template-columns:1fr}.panel,.metrics article{padding:16px}.inline,.filters{display:grid}.actions{flex-wrap:wrap}th,td{white-space:nowrap}h1{font-size:2rem}}`
